/**
 * SPEC0259 §4.11 — ephemeral CA and two leaves for the three-host proof
 * (test support only): one leaf with the SAN of every synthetic `.test` host
 * and one for the IdP (`localhost`). Generated by `openssl` in a temporary
 * directory that the caller removes; nothing is versioned. The SPKI pins feed
 * Chromium's `--ignore-certificate-errors-spki-list` (PB10).
 */
import { execFileSync } from 'node:child_process'
import { readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

export const TEST_HOSTS = [
  'console.cvg.test',
  'api.cvg.test',
  'mirror.cvg.test',
  'reports.cvg.test',
  'sibling.cvg.test',
  'evil.other.test'
] as const

export interface ProofLeaf {
  readonly key: Buffer
  readonly cert: Buffer
  /** base64 SHA-256 of the SubjectPublicKeyInfo. */
  readonly spki: string
}

export interface ProofCertificates {
  readonly caFile: string
  readonly ca: Buffer
  readonly test: ProofLeaf
  readonly idp: ProofLeaf
}

function openssl(directory: string, args: string[], input?: Buffer): Buffer {
  return execFileSync('openssl', args, {
    cwd: directory,
    stdio: ['pipe', 'pipe', 'pipe'],
    ...(input ? { input } : {})
  })
}

function leaf(
  directory: string,
  name: string,
  sans: readonly string[]
): ProofLeaf {
  openssl(directory, [
    'req',
    '-newkey',
    'rsa:2048',
    '-nodes',
    '-keyout',
    `${name}.key`,
    '-subj',
    `/CN=${sans[0]}`,
    '-out',
    `${name}.csr`
  ])
  writeFileSync(
    join(directory, `${name}.ext`),
    [
      'basicConstraints=CA:FALSE',
      'keyUsage=digitalSignature,keyEncipherment',
      'extendedKeyUsage=serverAuth',
      `subjectAltName=${sans.map((san) => `DNS:${san}`).join(',')}`
    ].join('\n')
  )
  openssl(directory, [
    'x509',
    '-req',
    '-in',
    `${name}.csr`,
    '-CA',
    'ca.crt',
    '-CAkey',
    'ca.key',
    '-CAcreateserial',
    '-days',
    '2',
    '-sha256',
    '-extfile',
    `${name}.ext`,
    '-out',
    `${name}.crt`
  ])
  const publicKey = openssl(directory, [
    'x509',
    '-in',
    `${name}.crt`,
    '-pubkey',
    '-noout'
  ])
  const der = openssl(
    directory,
    ['pkey', '-pubin', '-outform', 'der'],
    publicKey
  )
  const spki = openssl(directory, ['dgst', '-sha256', '-binary'], der).toString(
    'base64'
  )
  return {
    key: readFileSync(join(directory, `${name}.key`)),
    cert: readFileSync(join(directory, `${name}.crt`)),
    spki
  }
}

export function createProofCertificates(directory: string): ProofCertificates {
  openssl(directory, [
    'req',
    '-x509',
    '-newkey',
    'rsa:2048',
    '-nodes',
    '-keyout',
    'ca.key',
    '-subj',
    '/CN=CVG SPEC0259 ephemeral test CA',
    '-days',
    '2',
    '-addext',
    'basicConstraints=critical,CA:TRUE',
    '-addext',
    'keyUsage=critical,keyCertSign,cRLSign',
    '-out',
    'ca.crt'
  ])
  return {
    caFile: join(directory, 'ca.crt'),
    ca: readFileSync(join(directory, 'ca.crt')),
    test: leaf(directory, 'hosts', TEST_HOSTS),
    idp: leaf(directory, 'idp', ['localhost'])
  }
}
